#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, d, m, money = 0;
    cin >> n >> d;

    int* a = new int[n];
    for (int i = 0; i < n; ++i)
        cin >> a[i];

    cin >> m;
    sort(a, a + n);

    for (int i = 0; i < min(n, m); ++i)
        money += a[i];

    if (m > n)
        money -= (m - n) * d;

    cout << money;

    delete[] a;
    return 0;
}

